/*
  A pose is where one piece is. A formation is a pose for every piece plus how
  the whole stack is turned and placed. The scene at rest on a beat is one
  formation; moving between beats is a blend of two.
*/

export type Vec3 = [number, number, number];

export type Pose = {
  position: Vec3;
  /** Euler angles in radians, applied in X, Y, Z order. */
  rotation: Vec3;
  /** Width and height. */
  size: [number, number];
};

export type Formation = {
  pieces: Pose[];
  /** How the whole stack is turned, about X then Y, in radians. */
  turn: [number, number];
  /**
   * Where the stack sits on a wide screen, as a share of half the screen:
   * 0.5 across is halfway from the middle to the right edge. Narrow screens
   * centre it.
   */
  anchor: [number, number];
  /** How much the pieces drift while idle, 0 to 1. */
  drift: number;
  /** How wide the formation is, so the camera can stand back far enough. */
  span: number;
  /** How tall it is, for the same reason. */
  rise: number;
  /** The closest the camera comes to the formation. */
  near: number;
  /**
   * How the view changes while the beat is scrolled through: the turn about
   * X, the turn about Y, and the distance, each centred on the formation's
   * own.
   */
  sway: Vec3;
  /** The height of the floor under the formation. */
  floor: number;
  /**
   * 1 when the formation stands over the caption's column on a wide screen,
   * and not beside the caption, so that it has to be fitted above the text
   * on a screen shorter than the one it was framed on. See camera.ts.
   */
  over: number;
};

export const lerp = (a: number, b: number, t: number): number => a + (b - a) * t;

/** 0 below `a`, 1 above `b`, and a smooth S-curve in between. */
export function smoothstep(x: number, a: number, b: number): number {
  if (a === b) return x < a ? 0 : 1;
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
}

const clamp01 = (x: number): number => Math.min(1, Math.max(0, x));

/** The share of a move over which the pieces set off, one after another. */
export const SPREAD = 0.45;

/**
 * One piece's own progress through a move that is `t` of the way along. The
 * first piece sets off at once and the last when `spread` of the move has
 * gone; each then takes the time that is left. With no spread they move as
 * one.
 */
export function stagger(t: number, i: number, count: number, spread: number): number {
  if (!(spread > 0) || count <= 1) return clamp01(t);
  const share = Math.min(spread, 0.95);
  const start = (share * i) / (count - 1);
  return clamp01((t - start) / (1 - share));
}

/** A formation with every piece at the origin, to be written into. */
export function blankFormation(count: number): Formation {
  return {
    pieces: Array.from(
      { length: count },
      (): Pose => ({ position: [0, 0, 0], rotation: [0, 0, 0], size: [1, 1] }),
    ),
    turn: [0, 0],
    anchor: [0, 0],
    drift: 0,
    span: 0,
    rise: 0,
    near: 0,
    sway: [0, 0, 0],
    floor: 0,
    over: 0,
  };
}

/**
 * Writes the blend of `a` and `b` into `out` and returns it. It allocates
 * nothing, so it can run every frame. `a` and `b` must have at least as many
 * pieces as `out`.
 *
 * `each`, when given, is every piece's own progress, so the pieces can move
 * one after another. What belongs to the whole stack always moves by `t`.
 */
export function mixFormation(
  out: Formation,
  a: Formation,
  b: Formation,
  t: number,
  each?: ArrayLike<number>,
): Formation {
  for (let i = 0; i < out.pieces.length; i++) {
    const piece = out.pieces[i];
    const from = a.pieces[i];
    const to = b.pieces[i];
    const own = each ? each[i] : t;
    for (let k = 0; k < 3; k++) {
      piece.position[k] = lerp(from.position[k], to.position[k], own);
      piece.rotation[k] = lerp(from.rotation[k], to.rotation[k], own);
    }
    piece.size[0] = lerp(from.size[0], to.size[0], own);
    piece.size[1] = lerp(from.size[1], to.size[1], own);
  }
  out.turn[0] = lerp(a.turn[0], b.turn[0], t);
  out.turn[1] = lerp(a.turn[1], b.turn[1], t);
  out.anchor[0] = lerp(a.anchor[0], b.anchor[0], t);
  out.anchor[1] = lerp(a.anchor[1], b.anchor[1], t);
  out.drift = lerp(a.drift, b.drift, t);
  out.span = lerp(a.span, b.span, t);
  out.rise = lerp(a.rise, b.rise, t);
  out.near = lerp(a.near, b.near, t);
  for (let k = 0; k < 3; k++) out.sway[k] = lerp(a.sway[k], b.sway[k], t);
  out.floor = lerp(a.floor, b.floor, t);
  out.over = lerp(a.over, b.over, t);
  return out;
}

/**
 * How far the view has swung from where the formations put it: about X,
 * about Y, and in distance. `dwell` is how far through its rest `a` is; `b`
 * has not begun its own.
 */
export function swing(
  out: Vec3,
  a: Formation,
  b: Formation,
  t: number,
  dwell: number,
): Vec3 {
  for (let k = 0; k < 3; k++) {
    out[k] = lerp(a.sway[k] * (dwell - 0.5), b.sway[k] * -0.5, t);
  }
  return out;
}

/** A beat may keep moving while it rests, driven only by its scroll dwell. */
export type BeatFormation = { rest: Formation; within?: Formation };

/** Writes a beat's current resting pose without changing its source data. */
export function atRest(out: Formation, beat: BeatFormation, dwell: number): Formation {
  const progress = Number.isFinite(dwell) ? Math.min(1, Math.max(0, dwell)) : 0;
  return mixFormation(out, beat.rest, beat.within ?? beat.rest, progress);
}
import type { BeatFormation, Formation } from "./formation.ts";

export type ChapterRole = "opening" | "who" | "where" | "how" | "what" | "outcomes" | "others" | "close";
export type BeatDef = { id: string; height: number };
export type ChapterDef = {
  id: string;
  number: number;
  name: string;
  role: ChapterRole;
  beats: readonly BeatDef[];
};
export type StoryDef = { pieces: number; chapters: readonly ChapterDef[] };
export type BeatIdOf<S extends StoryDef> = S["chapters"][number]["beats"][number]["id"];

/** Beats are flattened in reading order; the story remains the source of truth. */
export function beatsOf<S extends StoryDef>(story: S): S["chapters"][number]["beats"][number][] {
  return story.chapters.flatMap((chapter) => chapter.beats);
}

export function beatIndex(story: StoryDef, id: string): number {
  return beatsOf(story).findIndex((beat) => beat.id === id);
}

export function beatHeight(story: StoryDef, id: string): number {
  const beat = beatsOf(story).find((entry) => entry.id === id);
  if (!beat) throw new Error(`Unknown beat: ${id}`);
  return beat.height;
}

/** The chapter being read, including while travelling between two beats. */
export function chapterAt(story: StoryDef, beat: number): string | undefined {
  const chapters = story.chapters.flatMap((chapter) => chapter.beats.map(() => chapter.id));
  const nearest = Number.isFinite(beat) ? Math.round(beat) : 0;
  return chapters[Math.min(Math.max(nearest, 0), chapters.length - 1)];
}

export function chapterNear(story: StoryDef, id: string, beat: number, reach = 1.5): boolean {
  let first = 0;
  for (const chapter of story.chapters) {
    if (chapter.id === id) {
      return chapter.beats.length > 0 && beat >= first - reach && beat <= first + chapter.beats.length - 1 + reach;
    }
    first += chapter.beats.length;
  }
  return false;
}

export function chapterNumber(story: StoryDef, id: string): number {
  return story.chapters.find((chapter) => chapter.id === id)?.number ?? 0;
}

/** Reports content mistakes before the scene tries to render the bundle. */
export function checkStory(
  story: StoryDef,
  formations: Readonly<Partial<Record<string, BeatFormation>>>,
  faces: readonly { beat: string; piece: number }[] = [],
): string[] {
  const problems: string[] = [];
  if (!Number.isInteger(story.pieces) || story.pieces < 1) problems.push("pieces must be a positive integer");
  if (story.chapters.length === 0) problems.push("story must have a chapter");
  const ids = new Set<string>();
  const beats = new Set<string>();
  const register = (id: string) => {
    if (!id.trim()) problems.push("id must not be empty");
    if (ids.has(id)) problems.push(`id used twice: ${id}`);
    ids.add(id);
  };
  const inspect = (formation: Formation, label: string) => {
    if (formation.pieces.length !== story.pieces) problems.push(`${label}: wrong number of poses (${formation.pieces.length}, expected ${story.pieces})`);
    const values = [
      ...formation.turn, ...formation.anchor, ...formation.sway,
      formation.drift, formation.span, formation.rise, formation.near, formation.floor, formation.over,
      ...formation.pieces.flatMap((pose) => [...pose.position, ...pose.rotation, ...pose.size]),
    ];
    if (!values.every(Number.isFinite)) problems.push(`${label}: formation numbers must be finite`);
    if (formation.pieces.some((pose) => pose.size.some((size) => size <= 0))) problems.push(`${label}: piece sizes must be positive`);
    if (formation.span < 0 || formation.rise < 0 || formation.near < 0) problems.push(`${label}: framing dimensions must not be negative`);
  };
  for (const chapter of story.chapters) {
    register(chapter.id);
    if (!Number.isFinite(chapter.number)) problems.push(`${chapter.id}: chapter number must be finite`);
    if (chapter.beats.length === 0) problems.push(`${chapter.id}: chapter must have a beat`);
    for (const beat of chapter.beats) {
      register(beat.id);
      beats.add(beat.id);
      if (!Number.isFinite(beat.height) || beat.height < 1) problems.push(`${beat.id}: height must be finite and at least 1`);
      const formation = formations[beat.id];
      if (!formation) problems.push(`${beat.id}: missing formation`);
      else {
        inspect(formation.rest, `${beat.id}.rest`);
        if (formation.within) inspect(formation.within, `${beat.id}.within`);
      }
    }
  }
  for (const id of Object.keys(formations)) {
    if (!beats.has(id)) problems.push(`formation names missing beat: ${id}`);
  }
  for (const face of faces) {
    if (!beats.has(face.beat)) problems.push(`face names missing beat: ${face.beat}`);
    if (!Number.isInteger(face.piece) || face.piece < 0 || face.piece >= story.pieces) problems.push(`face names missing piece: ${face.piece}`);
  }
  return problems;
}
import { Chapter, Beat, Kicker, Title, Body, Note } from "@/components/story/chapter";
import { Experience } from "@/content/experience";
import { story } from "@/content/story";
import { copy } from "@/content/copy";

export default function Home() {
  return <main><a className="story-skip" href="#close">{copy.skipLabel}</a><Experience>
    {story.chapters.map((chapter, index) => <Chapter key={chapter.id} id={chapter.id}>
      {chapter.beats.map((beat, beatIndex) => {
        const words = copy.beats[beat.id];
        return <Beat key={beat.id} story={story} id={beat.id} fallback={index === 1 ?
          // A local SVG is already sized; no image optimizer or network is needed.
          // eslint-disable-next-line @next/next/no-img-element
          <img src="/plain/fan.svg" width="640" height="300" alt={copy.pictureAlt} /> : undefined}>
          <Kicker number={chapter.number}>{chapter.name}</Kicker>
          <Title id={`${beatIndex === 0 ? chapter.id : beat.id}-title`} as={index === 0 && beatIndex === 0 ? "h1" : "h2"}>{words.title}</Title>
          <Body>{words.body}</Body>
          <Note>{words.note}</Note>
          {index === 2 && <a href="#opening">{copy.backLabel}</a>}
        </Beat>;
      })}
